package com.campusly.web;
import com.campusly.api.ApiModels.*; import com.campusly.data.ApplicationRepository; import com.campusly.data.OpportunityRepository; import com.campusly.data.UserRepository; import com.campusly.domain.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.List; import java.util.UUID;
@RestController @RequestMapping("/api/applications")
public class ApplicationController {
 private final ApplicationRepository applications;private final OpportunityRepository opportunities;private final UserRepository users;
 public ApplicationController(ApplicationRepository applications,OpportunityRepository opportunities,UserRepository users){this.applications=applications;this.opportunities=opportunities;this.users=users;}
 @GetMapping public List<ApplicationView> mine(Authentication auth){UserAccount user=current(auth);return applications.findAllByStudentIdOrderByAppliedAtDesc(user.getId()).stream().map(this::view).toList();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public ApplicationView apply(Authentication auth,@Valid @RequestBody ApplicationRequest body){UserAccount user=current(auth);Opportunity opportunity=opportunities.findById(body.opportunityId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Opportunity not found."));if(applications.existsByStudentIdAndOpportunityId(user.getId(),opportunity.getId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"You already applied to this opportunity.");if(opportunity.getDeadline().isBefore(java.time.LocalDate.now()))throw new ResponseStatusException(HttpStatus.GONE,"This opportunity has closed.");return view(applications.save(new StudentApplication(user,opportunity,body.note())));}
 @PatchMapping("/{id}/status") @PreAuthorize("hasRole('ADMIN')") public ApplicationView status(@PathVariable UUID id,@Valid @RequestBody ApplicationStatusRequest body){if(!List.of("Submitted","In review","Interview","Rejected","Accepted").contains(body.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported application status.");StudentApplication app=applications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));app.setStatus(body.status());return view(applications.save(app));}
 private UserAccount current(Authentication auth){return users.findById(UUID.fromString(auth.getName())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private ApplicationView view(StudentApplication a){Opportunity o=a.getOpportunity();return new ApplicationView(a.getId(),o.getId(),o.getTitle(),o.getOrganization(),o.getCategory(),a.getStatus(),a.getAppliedAt(),a.getNote());}
}
